import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        int[] len = new int[n];
        int[][] freq = new int[n][26];
        for (int i = 0; i < n; i++) {
            String w = next();
            len[i] = w.length();
            for (int t = 0; t < w.length(); t++) freq[i][w.charAt(t) - 'a']++;
        }
        int answer = -1;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < i; j++) {
                int diff = Math.abs(len[i] - len[j]);
                if (diff <= answer) continue;
                // Common features: sum over letters of the smaller count.
                int common = 0;
                for (int c = 0; c < 26 && common <= k; c++) common += Math.min(freq[i][c], freq[j][c]);
                if (common <= k) answer = Math.max(answer, diff);
            }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	length := make([]int, n)
	freq := make([][26]int, n)
	for i := 0; i < n; i++ {
		w := nextToken()
		length[i] = len(w)
		for _, c := range w {
			freq[i][c-'a']++
		}
	}
	answer := -1
	for i := 0; i < n; i++ {
		for j := 0; j < i; j++ {
			diff := length[i] - length[j]
			if diff < 0 {
				diff = -diff
			}
			if diff <= answer {
				continue
			}
			// Common features: sum over letters of the smaller count.
			common := 0
			for c := 0; c < 26 && common <= k; c++ {
				common += min(freq[i][c], freq[j][c])
			}
			if common <= k {
				answer = max(answer, diff)
			}
		}
	}
	fmt.Println(answer)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
